{"action": "run", "code": "await tab.waitForSelector('.login-form input:not([type="password"])');
await tab.fill('.login-form input:not([type="password"])', 'demo');
await tab.fill('.login-form input[type="password"]', 'demo123');
await tab.click('.primary-button');
await tab.waitForSelector('.app-header', { timeout: 20000 });
const header = await tab.evaluate(() => {
  const h = document.querySelector('.app-header');
  return h ? h.innerText : null;
});
const bodyText = await tab.evaluate(() => document.body.innerText);
const hasOrdersHeading = bodyText.includes('ÓRDENES DE MOVIMIENTO');
const hasErrorBox = !!document.querySelector('.error-box');
const hasRestricted = bodyText.includes('ACCESO RESTRINGIDO');
const hasEmpty = bodyText.includes('SIN ÓRDENES PENDIENTES');
return { header, hasOrdersHeading, hasErrorBox, hasRestricted, hasEmpty };"}

