{"action": "run", "code": "const errorHtml = await tab.evaluate(() => {
  const el = document.querySelector('.error-box');
  return el ? el.innerHTML : null;
});
const storage = await tab.evaluate(() => {
  const out = {};
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    out[k] = localStorage.getItem(k).slice(0, 300);
  }
  return out;
});
return { errorHtml, storage };"}

